from taf.ul.ettf.events.event import Event


class LogCollected(Event):

    def paths(self):
        pass


class SyslogCollected(LogCollected):
    def __init__(self, *paths):
        self._paths = list(paths)

    def __str__(self):
        return 'Syslog collection'

    @property
    def paths(self):
        return self._paths
